// Hand-crafted, tapered evaluation.
//
// Every term is a (middlegame, endgame) pair taken from one flat parameter
// array, and every feature enters the score linearly: eval = sum(w_i * f_i),
// interpolated between the middlegame and endgame halves by game phase. That
// linearity is what makes the weights tunable: trace() reports the feature
// counts f_i for a position, and tools/tune fits w_i by logistic regression
// against game results (Texel's method). The weights in eval_params.cpp are
// generated by that tool.
#pragma once

#include <string>

#include "core/position.h"

namespace chess::eval {

struct Score {
    int mg = 0;
    int eg = 0;

    constexpr Score() = default;
    constexpr Score(int m, int e) : mg(m), eg(e) {}
    constexpr Score operator+(Score o) const { return {mg + o.mg, eg + o.eg}; }
    constexpr Score operator-(Score o) const { return {mg - o.mg, eg - o.eg}; }
    constexpr Score operator*(int n) const { return {mg * n, eg * n}; }
    constexpr Score& operator+=(Score o) { return *this = *this + o; }
    constexpr Score& operator-=(Score o) { return *this = *this - o; }
};

// Layout of the parameter array. Each block is indexed as noted.
namespace idx {
constexpr int Material = 0;                        // [piece type], king unused
constexpr int Pst = Material + 6;                  // [piece type][square from the side's own view]
constexpr int KnightMobility = Pst + 6 * 64;       // [number of safe target squares]
constexpr int BishopMobility = KnightMobility + 9;
constexpr int RookMobility = BishopMobility + 14;
constexpr int QueenMobility = RookMobility + 15;
constexpr int PassedPawn = QueenMobility + 28;     // [relative rank]
constexpr int IsolatedPawn = PassedPawn + 8;
constexpr int DoubledPawn = IsolatedPawn + 1;
constexpr int ConnectedPawn = DoubledPawn + 1;     // [relative rank], supported or side by side
constexpr int BishopPair = ConnectedPawn + 8;
constexpr int RookOpenFile = BishopPair + 1;
constexpr int RookSemiOpenFile = RookOpenFile + 1;
constexpr int KingShield = RookSemiOpenFile + 1;   // [0] pawns one rank ahead, [1] two ranks ahead
constexpr int KingZoneAttack = KingShield + 2;     // [N, B, R, Q] attacked squares near the enemy king
constexpr int PawnThreat = KingZoneAttack + 4;     // enemy pieces attacked by our pawns
constexpr int Tempo = PawnThreat + 1;
constexpr int Count = Tempo + 1;
}  // namespace idx

extern const Score Params[idx::Count];

constexpr int PHASE_MAX = 24;      // knights/bishops 1, rooks 2, queens 4
constexpr int SCALE_NORMAL = 128;  // endgame scale factor denominator

// Feature counts of one position: coef[i][c] is how often parameter i applies
// to colour c. The white-relative evaluation is
//   (mg * phase + eg * (24 - phase) * eg_scale / 128) / 24
// with mg/eg = sum_i (coef[i][WHITE] - coef[i][BLACK]) * Params[i].
struct Trace {
    int coef[idx::Count][COLOR_NB] = {};
    int phase = 0;
    int eg_scale = SCALE_NORMAL;
};

// Static evaluation from the side to move's point of view, in centipawns.
Value evaluate(const Position& pos);

// Same computation, additionally recording feature counts. Returns the
// white-relative evaluation.
Value trace(const Position& pos, Trace& out);

}  // namespace chess::eval
